const PROVIDERS = [
  { id: 'aws', name: 'AWS', color: '#FF9900' },
  { id: 'azure', name: 'Azure', color: '#0078D4' },
  { id: 'gcp', name: 'GCP', color: '#4285F4' },
  { id: 'cloudflare', name: 'Cloudflare', color: '#F6821F' }
];

const DETAILS = {
  "Virtual Machines": { when: "When you need full control over the OS, persistent long-running workloads, or must run software that assumes a traditional server.", why: "Some software assumes a full operating system - custom networking, legacy apps, specific kernel modules. Containers and serverless can't do that. VMs give you a complete machine without buying physical hardware." },
  "GPU / Accelerated Compute": { when: "When you're training ML models, running inference at scale, or doing GPU-heavy rendering and simulation.", why: "CPUs process instructions one at a time. GPUs process thousands in parallel. AI training, video rendering, and scientific simulation need this parallelism - a task that takes days on CPUs can finish in hours on GPUs." },
  "Spot / Preemptible Instances": { when: "When your workload is fault-tolerant and interruptible - batch processing, CI/CD, distributed training, or stateless web tiers.", why: "Cloud providers always have spare capacity sitting idle. Spot instances let you use it at 60-90% discount. The tradeoff - they can be reclaimed - is fine for workloads that can checkpoint and restart." },
  "Serverless Functions": { when: "When you have event-driven, short-lived tasks - API endpoints, webhooks, file processing, or glue logic between services.", why: "Running a server 24/7 for code that executes a few seconds per hour is wasteful. Serverless charges only for actual execution time and handles scaling automatically - from zero to thousands of concurrent runs." },
  "Stateful Serverless / Workflows": { when: "When your serverless logic needs to remember state across steps - multi-step approvals, long-running orchestrations, or saga patterns.", why: "Regular serverless functions forget everything between invocations. But many real workflows have steps: charge the card, then reserve inventory, then send confirmation. If step 2 fails, step 1 needs to be rolled back. Stateful serverless tracks this automatically." },
  "Container Orchestration": { when: "When you're running many microservices that need automated scaling, rolling deploys, and service discovery with Kubernetes.", why: "Running 3 containers is easy. Running 300 across 50 machines with zero-downtime deploys, automatic restarts, load balancing, and secret management is not. Kubernetes automates the hard parts of running containers at scale." },
  "Serverless Containers": { when: "When you want to run containers without managing clusters - deploy a Docker image and let the platform handle scaling to zero.", why: "Kubernetes is powerful but complex - you still manage nodes, networking, and cluster upgrades. Serverless containers give you container flexibility (any language, any binary) without any of the cluster management." },
  "Container Registry": { when: "When you need a private registry to store and scan container images close to your compute.", why: "Docker Hub is public. Your production images contain your code, configs, and sometimes secrets. A private registry keeps them secure and close to your deployment targets, reducing pull times and egress costs." },
  "App Platform / PaaS": { when: "When you want to deploy a web app from a Git repo without thinking about infrastructure.", why: "VMs require OS management. Containers require Dockerfiles and orchestration. PaaS skips all of it - push code, get a running app. The tradeoff is less control over the runtime, but for most web apps that's fine." },
  "Edge Compute": { when: "When latency matters more than anything - personalization, A/B testing, auth checks, or geo-routing close to the user.", why: "Physics limits speed. A request from Tokyo to Virginia takes ~150ms round trip. Edge compute runs your code in the city closest to each user, cutting that to single-digit milliseconds. Matters for real-time personalization and auth." },
  "Multi-Tenant Compute": { when: "When you're building a platform where each customer gets isolated compute - plugin systems, white-label SaaS, or marketplace apps.", why: "If you let customers run custom code on your platform (like Shopify letting merchants run scripts), you need per-tenant isolation without per-tenant infrastructure cost. Traditional VMs or containers per tenant don't scale economically." },
  "Sandboxes": { when: "When you need to run untrusted user code safely - code playgrounds, AI agent tool execution, or plugin sandboxing.", why: "AI agents need to execute code they generate, but running untrusted code on your servers is dangerous. Sandboxes provide isolated environments that can't escape to your infrastructure, disposable after each use." },
  "Dynamic Workers": { when: "When your application needs to spawn Workers on the fly from user-provided or AI-generated code at runtime.", why: "Regular Workers are deployed ahead of time. But AI agents generate code dynamically - they need to compile and run it immediately without a deploy step. Dynamic Workers bridge this gap." },
  "Cron / Scheduled Jobs": { when: "When you need to run tasks on a schedule - cleanup jobs, report generation, data syncs, periodic health checks.", why: "Many tasks aren't triggered by user requests - they need to run at specific times. Database cleanup at 3am, daily reports at 8am, syncing data every 15 minutes. A scheduler triggers your code on these schedules reliably." },
  "Bare Metal Servers": { when: "When you need direct hardware access - high-frequency trading, license compliance, HSMs, or workloads that can't tolerate hypervisor overhead.", why: "Virtualization adds a small performance tax (typically 1-5%). For workloads where every microsecond matters, or where software licenses are per-physical-core, or where compliance requires physical isolation, you need the real hardware." },
  "Object Storage": { when: "When you need to store unstructured data - images, backups, logs, data lake files - with high durability and HTTP access.", why: "Traditional file systems hit limits - they're tied to one server, hard to scale, and a disk failure can lose data. Object storage is distributed, virtually unlimited, eleven-nines durable, and accessible from anywhere via HTTP." },
  "Block Storage": { when: "When your VM needs a persistent disk - databases, file systems, or any workload requiring low-latency attached storage.", why: "VMs need disk. Object storage is too slow for databases (it's accessed via HTTP). Block storage provides the same low-latency random I/O as a local SSD, but it's networked - so it survives VM termination and can be snapshotted." },
  "File Storage": { when: "When multiple servers need to read/write the same files concurrently - shared config, CMS uploads, or apps expecting POSIX.", why: "Block storage attaches to one VM. But some workloads need shared access - a pool of web servers reading the same uploaded files, or a container cluster sharing config. Network file systems (NFS/SMB) solve this." },
  "Archive / Cold Storage": { when: "When you have data you must keep for compliance or DR but rarely access - audit logs, old backups, raw research data.", why: "Standard storage costs add up when you have petabytes of data you access once a year. Archive storage trades retrieval speed (minutes to hours) for dramatically lower cost - sometimes 20x cheaper than standard tiers." },
  "Edge / Cache Storage": { when: "When you need key-value data readable at the edge with low latency - feature flags, config, redirects, personalization.", why: "Databases are in one region. If your edge function needs to look up a feature flag or redirect rule, hitting a database in Virginia from Tokyo adds 150ms+. Edge KV stores replicate data to every edge location for instant reads." },
  "Managed Backup": { when: "When you need centralized, policy-driven backups across VMs, databases, file systems with compliance reporting.", why: "Each cloud service has its own backup mechanism. Managing backup schedules, retention, cross-region copies, and compliance reporting across dozens of services individually is error-prone. Centralized backup provides one policy engine for everything." },
  "Managed Relational Database": { when: "When your app needs a relational database but you don't want to manage patching, backups, replication, and failover.", why: "Running your own database means you handle OS patching, version upgrades, backup schedules, replication setup, failover testing, and storage scaling. Managed databases automate all of it so you focus on your schema and queries." },
  "NoSQL / Document Database": { when: "When your data model is flexible, access patterns are key-based, and you need single-digit millisecond reads at any scale.", why: "Relational databases enforce rigid schemas and struggle to scale horizontally. If your data is naturally document-shaped (user profiles, product catalogs, game state), NoSQL lets you iterate on the schema without migrations and scale to millions of reads/second." },
  "In-Memory Cache": { when: "When your database is the bottleneck and you need sub-millisecond reads - session stores, leaderboards, rate limiting, hot query caching.", why: "Databases store data on disk. Even SSDs have microsecond latency. RAM is 100x faster. Caching your most-read data in memory dramatically reduces database load and response times - the difference between 50ms and 1ms page loads." },
  "Data Warehouse": { when: "When you need to run analytical queries across terabytes of structured data - BI dashboards, ad-hoc analysis, data science.", why: "Operational databases (MySQL, Postgres) are optimized for small, fast reads/writes. Running a complex analytics query across billions of rows would bring your production database to its knees. Data warehouses use columnar storage optimized for exactly these queries." },
  "Vector Database": { when: "When you're building AI features that need semantic search, RAG, or similarity matching over embeddings.", why: "Traditional search matches keywords. But 'affordable Italian restaurant' should match 'budget-friendly trattoria' even though they share no words. Vector databases store the meaning of content as numbers (embeddings) and find similar items by mathematical distance." },
  "Database Connection Pooling": { when: "When serverless functions are exhausting your database connection limit - each invocation opens a new connection.", why: "Databases support a limited number of connections (typically hundreds to low thousands). Serverless functions are stateless - each one opens a fresh connection. At 1000 concurrent functions, you hit the limit. A pooler shares a smaller set of connections across all callers." },
  "Graph Database": { when: "When your queries are about relationships - social networks, fraud detection, recommendation engines, knowledge graphs.", why: "SQL can handle relationships with JOINs, but 'find all friends of friends who also bought product X within the last month' requires multiple nested JOINs that get exponentially slower. Graph databases store relationships as first-class citizens, making traversals fast at any depth." },
  "Time Series Database": { when: "When you're ingesting timestamped data at high volume - IoT sensors, app metrics, financial tick data.", why: "General-purpose databases treat time as just another column. Time series databases are built around it - they compress timestamps efficiently, handle high-write throughput, provide time-window queries natively, and automatically downsample old data." },
  "Managed Kafka": { when: "When you need durable, ordered, high-throughput event streaming - real-time pipelines, event sourcing, CDC.", why: "Message queues (SQS) deliver and delete. Kafka keeps an ordered log that multiple consumers can read at their own pace, replay from any point, and process in parallel. Essential for event-driven architectures, but notoriously hard to operate yourself." },
  "Virtual Private Cloud": { when: "You need isolated network segments for your cloud workloads with custom IP ranges and routing.", why: "Without a VPC, your cloud resources share a flat network with every other customer. VPCs give you isolation - your own IP space, subnets, routing tables, and firewall rules. It's the equivalent of having your own data center network." },
  "VPC Peering / Transit": { when: "You have multiple VPCs that need to talk without traversing the public internet.", why: "Large organizations use separate VPCs for different teams, environments, or regions. These VPCs are isolated by default. Peering/transit connects them privately so services can communicate without exposing traffic to the internet." },
  "Private Link": { when: "You want to access cloud services across accounts or VPCs without public IPs or firewall rules.", why: "By default, accessing cloud services (like S3 or RDS) goes over the internet. Private Link creates a private network path - your traffic never leaves the cloud provider's backbone. Required for compliance in finance, healthcare, and government." },
  "NAT Gateway": { when: "Your private subnet instances need outbound internet access but shouldn't be directly reachable.", why: "Best practice puts servers in private subnets with no public IP. But they still need outbound access - software updates, external APIs. NAT translates their private IPs to a public one for outbound traffic while blocking inbound." },
  "DNS": { when: "You need authoritative DNS hosting with high availability, low latency, and programmable records.", why: "Every internet request starts with DNS. If your DNS is slow or goes down, nothing works. Managed DNS provides global anycast distribution, DDoS resilience, and millisecond resolution that self-hosted DNS can't match." },
  "DNS Firewall": { when: "You want to block DNS queries to known malicious domains before connections are established.", why: "DNS is the first step of every internet connection. Blocking a malicious domain at DNS level stops the threat before any TCP connection is established - faster and cheaper than inspecting the actual traffic." },
  "Internal / Private DNS": { when: "Your services need to resolve each other by name within a private network.", why: "Hardcoding IP addresses is fragile - IPs change when services move. Private DNS lets services find each other by name (api.internal, db.internal) without exposing those names to the public internet." },
  "CDN": { when: "You need to cache and deliver content closer to users to reduce latency and origin load.", why: "Your server is in one location. Your users are worldwide. A CDN caches copies of your content at hundreds of edge locations. User in Tokyo gets the cached version from Tokyo instead of waiting for a response from Virginia." },
  "Load Balancer": { when: "You need to distribute traffic across backends with health checks and automatic failover.", why: "One server has limits - it can crash, it can get overwhelmed. A load balancer spreads traffic across multiple servers, detects when one is unhealthy, and stops sending it traffic. Essential for availability and scaling." },
  "DDoS Protection": { when: "You run public-facing services and need to absorb volumetric attacks without manual intervention.", why: "Anyone on the internet can flood your IP with traffic. A sufficiently large DDoS can saturate your bandwidth and take you offline. DDoS protection has network capacity orders of magnitude larger than any attacker, absorbing the flood at the edge." },
  "Web Application Firewall": { when: "You need to filter malicious HTTP traffic like SQL injection, XSS, and zero-day exploits.", why: "Your application code has vulnerabilities - every application does. A WAF inspects every HTTP request against known attack patterns and blocks them before they reach your code. It's a safety net for the bugs you haven't found yet." },
  "Network Firewall": { when: "You need stateful packet inspection and protocol-level filtering for traffic inside your VPC.", why: "WAFs only inspect HTTP. Network firewalls inspect all traffic at the packet level - TCP, UDP, ICMP. They catch threats that aren't HTTP-based: port scans, lateral movement, protocol anomalies inside your network." },
  "API Gateway": { when: "You need to front your APIs with auth, rate limiting, transformation, and usage analytics.", why: "Without a gateway, every API backend implements its own auth, rate limiting, and logging. An API gateway centralizes these cross-cutting concerns in one place, so backends focus on business logic." },
  "Private / Dedicated Connectivity": { when: "You need a private connection between your data center and cloud that doesn't traverse the internet.", why: "Internet paths are unpredictable - congestion, route changes, and latency spikes. Dedicated connections provide guaranteed bandwidth, consistent latency, and bypass the public internet entirely for compliance." },
  "Domain Registration": { when: "You need to buy and manage domains with DNS integrated into your stack.", why: "Domains are your identity on the internet. Some registrars mark up prices heavily on renewals or charge for basic features like WHOIS privacy. Having registration and DNS in one place simplifies management." },
  "Smart Routing": { when: "Your users are global and traffic needs the fastest path, not just the default BGP route.", why: "BGP routes packets based on network topology, not speed. The shortest path isn't always the fastest - it might go through congested links. Smart routing monitors real-time conditions and picks actually faster paths." },
  "TCP/UDP Proxy": { when: "You need DDoS protection for non-HTTP protocols like gaming servers, SSH, or custom TCP services.", why: "Most edge security products only handle HTTP. But game servers, email, SSH, and custom protocols use raw TCP/UDP. Without a proxy, these services have no DDoS protection and no edge acceleration." },
  "Network-Level DDoS (L3/L4)": { when: "You advertise your own IP space and need volumetric DDoS scrubbing at the network layer.", why: "Website DDoS protection works at HTTP level. But if you own IP ranges (ISPs, hosting providers, enterprises), attackers can flood those IPs directly at the network layer. You need BGP-level scrubbing across a massive global network." },
  "SD-WAN": { when: "You need to connect branch offices and cloud with policy-based routing and centralized management.", why: "Traditional WAN uses expensive MPLS circuits ($$$) with rigid topology. SD-WAN uses the internet with intelligent overlay routing - cheaper, more flexible, and you can add/remove sites without provisioning physical circuits." },
  "Mesh Networking": { when: "You need automatic encrypted connectivity between distributed services without managing VPN tunnels.", why: "VPN tunnels are point-to-point. If you have 10 sites that all need to talk, you need 45 tunnels. Mesh networking automatically connects everything to everything with encrypted tunnels, without manual configuration." },
  "Multi-Cloud Networking": { when: "You run workloads across AWS, Azure, and GCP and need unified networking and security policies.", why: "Each cloud has its own networking model, its own firewall rules, its own VPN setup. Managing three separate networks is triple the work. A multi-cloud networking layer provides one set of policies across all of them." },
  "China Network": { when: "You need to serve content or run services for users in mainland China with acceptable performance.", why: "The Great Firewall adds significant latency and packet loss to traffic crossing China's border. A CDN presence inside China (via local partnerships) serves content locally, bypassing the bottleneck." },
  "Waiting Room": { when: "You expect traffic spikes (product drops, ticket sales) that could overwhelm your origin.", why: "When 100,000 people hit your site at once, your origin server crashes and nobody gets through. A waiting room queues excess visitors fairly instead of crashing - everyone gets in, just in order." },
  "BYOIP": { when: "You own IP address space and want to use it with a cloud provider's network.", why: "IP reputation matters - email deliverability, allowlists, client firewall rules all depend on your IPs. If you migrate clouds, changing IPs breaks all of that. BYOIP lets you keep your addresses while switching infrastructure." },
  "SSL for SaaS / Custom Domains": { when: "You build a SaaS platform and customers want their own domains with automatic HTTPS.", why: "Your SaaS customer wants shop.theirbrand.com, not yourplatform.com/theirbrand. Provisioning, renewing, and managing SSL certificates for thousands of customer domains manually is impossible. This automates the entire lifecycle." },
  "Identity & Access Management": { when: "You need to control who can access your cloud resources and what actions they can perform.", why: "Without IAM, everyone has admin access to everything. IAM enforces least-privilege - each person and service gets exactly the permissions they need and nothing more. Misconfigured IAM is the #1 cause of cloud breaches." },
  "Key Management": { when: "You need to create, rotate, and control encryption keys for data at rest and in transit.", why: "Encryption is only as secure as the keys. Storing keys in your code or on disk means anyone with server access can decrypt everything. KMS stores keys in tamper-resistant hardware (HSMs) that even cloud provider employees can't extract." },
  "Secrets Management": { when: "Your applications need database passwords, API keys, or tokens at runtime without hardcoding them.", why: "Secrets in source code end up in Git history, CI logs, and error messages. Secrets management provides a secure vault - apps fetch credentials at runtime, secrets can be rotated without redeploying, and access is audited." },
  "SSL / TLS Certificates": { when: "You need free, auto-renewing TLS certificates without managing CAs or renewal cron jobs.", why: "Without HTTPS, browsers show 'Not Secure' warnings and traffic can be intercepted. Managing certificates manually means tracking expiration dates and renewing them before they lapse (causing outages). Managed certs handle this automatically." },
  "Zero Trust Network Access": { when: "You want to replace your VPN with identity-aware access, verifying every request regardless of location.", why: "VPNs trust anyone on the network - once connected, you can access everything. Zero Trust verifies identity on every request to every app individually. A compromised device can't pivot to other services because there's no implicit trust." },
  "Secure Web Gateway": { when: "You need to inspect and filter outbound web traffic to block malware, phishing, and policy violations.", why: "Employees click phishing links and visit compromised sites. A gateway inspects all outbound traffic and blocks connections to known-bad destinations before malware is downloaded or credentials are submitted." },
  "Remote Browser Isolation": { when: "You want users to browse risky sites without code executing on their local device.", why: "Zero-day browser exploits can compromise a device just by visiting a page. Browser isolation runs the actual browsing in the cloud - the user sees a visual stream, but no code ever executes locally. Even a zero-day can't escape." },
  "VPN Client / Device Agent": { when: "You need encrypted tunnels from employee devices with device posture checks.", why: "On public WiFi, traffic can be intercepted. A VPN client encrypts all device traffic. Modern agents also check device posture (OS updated? disk encrypted? antivirus running?) before granting access." },
  "CASB": { when: "You need visibility into SaaS app usage, shadow IT detection, and security policy enforcement on third-party services.", why: "Employees use hundreds of SaaS apps. IT doesn't know about most of them. CASB discovers all SaaS usage, flags risky apps, and enforces policies - like preventing public file shares in Google Drive or detecting sensitive data in Slack." },
  "Data Loss Prevention": { when: "You need to detect and prevent sensitive data (credit cards, SSNs, secrets) from leaving your environment.", why: "Data leaks happen constantly - an employee emails a spreadsheet with customer SSNs, or pastes an API key in a public Slack channel. DLP scans traffic and content for sensitive patterns and blocks or alerts before data leaves." },
  "Bot Management": { when: "You need to distinguish real users from bots, blocking scrapers and credential stuffers while allowing good bots.", why: "Up to 40% of internet traffic is bots. Some are good (Google crawlers). Many are bad - scraping prices, stuffing stolen credentials, hoarding inventory. Bot management uses behavioral analysis to tell them apart." },
  "Rate Limiting": { when: "You need to throttle abusive clients hitting your APIs too fast.", why: "Without rate limits, a single client can monopolize your API, a brute-force attack can try millions of passwords, or a bug in a client can accidentally DDoS you. Rate limiting caps requests per client to protect availability for everyone." },
  "Email Security": { when: "You need to block phishing, BEC, and malicious attachments before they reach inboxes.", why: "Email is the #1 attack vector. Phishing emails impersonate trusted senders to steal credentials or deploy malware. Email security scans content, links, and attachments using threat intelligence to catch attacks that spam filters miss." },
  "DMARC Management": { when: "You want to prevent email spoofing of your domain and see who's sending as you.", why: "Anyone can send email claiming to be from your domain. DMARC tells receiving mail servers to reject unauthorized senders. Without it, attackers impersonate your brand in phishing campaigns targeting your customers." },
  "Client-Side / Page Security": { when: "You need to detect malicious third-party JavaScript injected via supply chain attacks.", why: "Your site loads scripts from third parties (analytics, chat, ads). If any of those scripts gets compromised, attackers can steal credit cards from your checkout page (Magecart attacks). Page security monitors these scripts for changes." },
  "Leaked Credentials Detection": { when: "You want to detect when users log in with credentials that appear in known breach databases.", why: "Billions of username/password pairs have been leaked from various breaches. Users reuse passwords. If someone logs into your site with a password leaked from another breach, their account is at risk. Detection flags these automatically." },
  "Fraud Detection": { when: "You need to identify account takeover, fake signups, or payment fraud on your web app.", why: "Bots and attackers follow patterns - rapid-fire login attempts, account creation from the same IP, unusual navigation sequences. Fraud detection tracks these patterns and scores requests for abuse signals." },
  "Smart Shield": { when: "You want automated security tuning that adjusts rules based on your traffic without manual config.", why: "Security rules require expertise to configure correctly. Too strict and you block real users. Too loose and you miss attacks. Auto-tuning analyzes your specific traffic patterns and adjusts automatically." },
  "Geo Key Manager": { when: "You need TLS private keys stored only in specific regions for data sovereignty compliance.", why: "On a global CDN, your TLS keys are at every edge location. Some regulations (GDPR) require that cryptographic keys never leave certain jurisdictions. Geo Key Manager restricts where your keys are stored and used." },
  "Security Posture / CSPM": { when: "You need a single dashboard to find misconfigs, compliance violations, and security risks.", why: "Cloud environments have hundreds of configuration knobs. An S3 bucket accidentally set to public, a security group allowing all inbound traffic, an unencrypted database - CSPM continuously scans for these mistakes." },
  "Threat Detection / SIEM": { when: "You need to aggregate security logs, detect threats with ML, and automate incident response.", why: "Attackers don't announce themselves. They leave traces across multiple services - an unusual API call here, a login from a new country there. SIEM correlates these signals across all your logs to detect attacks that no single log reveals." },
  "Data Localization": { when: "Regulations require your data is processed and stored only within specific countries.", why: "GDPR, data residency laws, and sector regulations restrict where data can flow. On a global CDN or edge network, your data is processed everywhere by default. Data localization forces processing to stay within approved regions." },
  "Digital Experience Monitoring": { when: "You need visibility into how employees experience apps - latency, packet loss, connectivity by device/location.", why: "When an employee says 'the app is slow,' you need to know if it's their WiFi, their ISP, your VPN, or the app itself. DEM tests the full path from device to app and pinpoints where degradation happens." },
  "ML Platform": { when: "You need to train, tune, and deploy custom ML models with managed infrastructure and experiment tracking.", why: "Training ML models requires GPUs, data pipelines, experiment tracking, model versioning, and deployment infrastructure. Building all this from scratch takes months. ML platforms provide it out of the box." },
  "AI Model APIs / Inference": { when: "You want to call foundation models via API without managing GPU infrastructure.", why: "Running LLMs requires expensive GPUs, model optimization expertise, and high availability infrastructure. API access lets you use the same models without any of that overhead - send text in, get intelligence out." },
  "AI Gateway / Proxy": { when: "You need rate limiting, caching, logging, and fallback routing in front of multiple LLM providers.", why: "AI APIs are expensive and unreliable. Identical prompts cost money every time. Providers have outages. A gateway caches repeat requests (saving money), logs everything (for debugging), and falls back to another provider when one is down." },
  "AI Search / RAG": { when: "You're building retrieval-augmented generation and need managed vector search plus document chunking.", why: "LLMs hallucinate when asked about your specific data. RAG grounds their answers in your actual documents by finding relevant chunks and including them in the prompt. Building this pipeline (chunking, embedding, indexing, retrieval) from scratch is complex." },
  "AI Agents SDK": { when: "You need a framework for multi-step AI agents with tool use, state, and orchestration at the edge.", why: "AI agents need to persist state between steps, call external tools, browse the web, and handle long-running tasks. Building this infrastructure (durable state, retries, scheduling) on top of raw LLM APIs is significant engineering work." },
  "Browser Rendering": { when: "Your AI agent or worker needs to navigate web pages, take screenshots, or extract content from JS-heavy sites.", why: "Modern websites render content with JavaScript - curl and HTTP requests only get empty HTML shells. Headless browsers execute JavaScript and render the full page, letting you extract content, take screenshots, and interact with web apps programmatically." },
  "Firewall for AI": { when: "You need to block prompt injection, PII leakage, or toxic content in AI inputs/outputs.", why: "LLM apps are vulnerable to prompt injection (users trick the model into ignoring instructions) and PII leakage (the model reveals training data or user data). An AI firewall inspects prompts and responses in real-time to catch these." },
  "AI Crawler Control": { when: "You want to see which AI bots scrape your site and selectively block or allow them.", why: "AI companies crawl websites for training data. Some respect robots.txt, many don't. Without visibility, you don't know who's taking your content or how much. Crawler control shows you exactly which bots visit and lets you decide per-bot." },
  "AI Dashboard Co-Pilot": { when: "You want a natural language assistant in your cloud console to query resources and debug issues.", why: "Cloud consoles have hundreds of pages and thousands of settings. Instead of navigating menus, you ask 'why is my worker failing?' or 'show me my most expensive resources' and get answers directly." },
  "Artifacts": { when: "You need a private package registry for Docker images, npm packages, or Python wheels in CI/CD.", why: "Public registries (npm, PyPI, Docker Hub) are fine for open-source. Your private code needs a private registry with access control, vulnerability scanning, and proximity to your build/deploy systems to avoid slow pulls." },
  "Speech AI": { when: "You need speech-to-text transcription or text-to-speech synthesis as a managed API.", why: "Building speech recognition from scratch requires massive training datasets and specialized ML expertise. Managed APIs provide state-of-the-art accuracy across languages out of the box, with a simple send-audio-get-text interface." },
  "Vision AI": { when: "You need pre-trained APIs for image classification, object detection, OCR, or face analysis.", why: "Training computer vision models requires millions of labeled images and GPU-months of training. Pre-built APIs give you production-quality results (detect objects, read text from images, moderate content) with a single API call." },
  "Natural Language Processing": { when: "You need entity extraction, sentiment analysis, or language detection without fine-tuning a model.", why: "Processing customer feedback at scale (is this review positive?), extracting entities from documents (which company names appear?), or detecting languages are common needs. Dedicated NLP APIs handle these without deploying a full LLM." },
  "CI/CD Pipeline": { when: "You need automated build, test, and deploy pipelines triggered by code pushes.", why: "Manual deployments are slow, error-prone, and don't scale. CI/CD automates the entire process - push code, tests run automatically, and if they pass, the new version deploys. This is how teams ship multiple times per day instead of once per month." },
  "Infrastructure as Code": { when: "You want to define and version infrastructure in code instead of clicking consoles.", why: "Clicking through a web console isn't repeatable, reviewable, or auditable. IaC lets you version-control your infrastructure, peer-review changes, and recreate your entire environment from scratch if disaster strikes." },
  "CLI Tool": { when: "You need to manage cloud resources from your terminal or automate in shell scripts.", why: "Web consoles are fine for exploring but terrible for automation. CLIs let you script operations, integrate with CI/CD, and manage resources faster than clicking through pages of UI." },
  "Feature Flags": { when: "You want to toggle features on/off for specific users without redeploying code.", why: "Deploying new code is risky. Feature flags let you ship code that's off by default, then gradually enable it for 1%, 10%, 50% of users. If something breaks, flip it off instantly without a rollback deploy." },
  "Rules Engine": { when: "You need to transform requests, rewrite URLs, set headers, or redirect traffic at the edge.", why: "Many request modifications (adding security headers, redirecting old URLs, rewriting paths) don't need application code changes. A rules engine handles these at the edge before requests reach your server, without deploys." },
  "Source Code Repository": { when: "You need managed Git integrated with your cloud's CI/CD and IAM.", why: "Git hosting with access control, branch protection, and CI/CD integration. Though most teams use GitHub or GitLab regardless of their cloud provider." },
  "Version Management": { when: "You need to manage multiple config versions and promote safely through environments.", why: "Changing production configuration is risky. Version management lets you make changes in staging, test them, then promote to production. If something breaks, instant rollback to the previous version." },
  "Tenant / Platform Management": { when: "You manage multiple accounts or clients and need centralized billing, policy, and access.", why: "MSPs and enterprises managing hundreds of accounts need centralized control - consistent security policies, consolidated billing, delegated access. Doing this account-by-account doesn't scale." },
  "Google Tag Gateway": { when: "You want server-side Google Tag Manager at the edge instead of in the browser.", why: "Client-side Google Tags slow down your page (JavaScript execution) and are blocked by ad blockers (losing analytics data). Server-side tagging moves the processing to the edge, improving both speed and data accuracy." },
  "Monitoring & Metrics": { when: "You need dashboards, metric collection, and alerting for infrastructure and applications.", why: "Without monitoring, you don't know something is broken until users complain. Metrics show CPU, memory, latency, error rates in real-time. Alarms wake you up at 3am when something crosses a threshold - before users notice." },
  "Logging": { when: "You need centralized log collection, search, and retention for debugging and compliance.", why: "When a request fails, you need the logs. But logs are spread across dozens of services and servers. Centralized logging aggregates everything into one searchable place so you can debug 'what happened at 3:47am' across your entire stack." },
  "Tracing": { when: "You need distributed tracing across microservices to find latency bottlenecks.", why: "A single user request might flow through 10 microservices. Each one looks fine individually. But the end-to-end request takes 3 seconds. Tracing follows the request through every hop and shows exactly where time is spent." },
  "Cost Management": { when: "You need to track, forecast, and optimize cloud spend across teams.", why: "Cloud bills are complex - hundreds of line items across dozens of services. Without cost management, you discover a $50K surprise at month end. Cost tools show where money goes in real-time and forecast future spend." },
  "Uptime & Health Checks": { when: "You need to monitor endpoint availability and get alerted when things go down.", why: "Your server can be down and you won't know until someone tells you. Health checks continuously ping your endpoints from multiple global locations and alert you the instant something is unreachable." },
  "Third-Party Script Management": { when: "You want to load analytics and marketing pixels without blocking page rendering or leaking data.", why: "Marketing teams add dozens of scripts (Google Analytics, chat widgets, A/B testing, pixels). Each one runs in the user's browser, slowing the page and potentially leaking data. Server-side management moves execution to the cloud." },
  "Network Error Logging": { when: "You need to know about TCP/TLS/DNS errors users hit that your server logs never see.", why: "When a user's connection fails before reaching your server (DNS timeout, TLS handshake failure, TCP reset), your server logs show nothing. NEL gets the browser to report these invisible failures back to you." },
  "Resource Tagging": { when: "You need to label resources for cost allocation, access control, or automation.", why: "With hundreds of cloud resources, you need to know which team owns what, which project it serves, and whether it's production or dev. Tags are metadata labels that enable cost allocation, access policies, and automated cleanup." },
  "Notifications / Alerting": { when: "You need to route alerts from monitoring to PagerDuty, Slack, or on-call teams.", why: "An alarm without a notification is useless. Alerting routes the right alerts to the right people via the right channel - critical alerts page on-call, warnings go to Slack, billing alerts go to email." },
  "Analytics API": { when: "You need programmatic access to traffic or usage analytics for custom dashboards.", why: "Built-in dashboards show predefined views. If you need custom views - correlating traffic data with business metrics, building internal dashboards, or feeding data into your own analytics stack - you need API access to raw data." },
  "Network Flow Monitoring": { when: "You need visibility into traffic patterns, top talkers, and potential exfiltration.", why: "Packet-level inspection is expensive and invasive. Flow monitoring captures metadata (source, destination, bytes, protocol) without inspecting content. Enough to detect anomalies, plan capacity, and investigate security incidents." },
  "Message Queue": { when: "You need reliable async message delivery between services with retries and dead letter handling.", why: "If Service A calls Service B directly and B is slow or down, A blocks or fails. A message queue decouples them - A drops a message and moves on. B processes it when ready. Failed messages get retried automatically." },
  "Event Bus / Streaming": { when: "You need to fan out events to multiple consumers or process high-throughput ordered streams.", why: "A queue delivers each message to one consumer. An event bus delivers each event to many consumers (billing AND shipping AND analytics all get the order event). Streaming adds ordering and replay for data pipelines." },
  "Push Notifications": { when: "You need to send push notifications to mobile apps or browsers at scale.", why: "Sending to millions of devices requires managing device tokens, platform differences (iOS vs Android), delivery receipts, and retry logic. Push notification services handle all this complexity behind a simple API." },
  "Email Service": { when: "You need to send transactional email at scale or route incoming email programmatically.", why: "Sending email reliably at scale is hard - IP reputation, SPF/DKIM/DMARC, bounce handling, deliverability monitoring, and ISP throttling. Email services manage all of this so your password reset emails actually arrive." },
  "Real-Time Communication": { when: "You need WebSocket-based real-time messaging, live cursors, or collaborative features.", why: "HTTP is request-response - the server can't push to the client. Real-time features (chat, live updates, collaborative editing) need persistent connections. WebSocket infrastructure handles connection management, presence, and message routing." },
  "Data Warehouse / SQL Analytics": { when: "You need ad-hoc SQL queries over terabytes of structured data for reporting.", why: "Your operational database serves your app. Running heavy analytical queries on it slows everything down. A data warehouse is a separate system optimized for analytical reads - columnar storage, massively parallel processing, and SQL access." },
  "Data Ingestion / Pipelines": { when: "You need to collect, transform, and load data from multiple sources into a warehouse or lake.", why: "Data lives in many places - databases, APIs, log files, event streams. Getting it all into your warehouse in the right format, on time, with error handling, is the plumbing that makes analytics possible. Boring but critical." },
  "Data Catalog": { when: "You need to discover, document, and govern data assets across your lakes and warehouses.", why: "As data grows, nobody knows what tables exist, what columns mean, or who owns what. A data catalog provides a searchable inventory of all data assets with schemas, owners, lineage, and quality metrics." },
  "Event Analytics": { when: "You need to write and query custom event data for product analytics or clickstream analysis.", why: "Tracking how users interact with your product (clicked button X, viewed page Y, completed signup) requires writing millions of events per day and querying aggregates in real-time. Too fast for a data warehouse, too complex for simple counters." },
  "Search Service": { when: "You need full-text search with faceting, ranking, and autocomplete for your app.", why: "SQL LIKE queries are slow and dumb - they can't rank results by relevance, handle typos, or provide faceted filtering. Search engines build inverted indexes that handle all of this, powering search bars that users expect to work like Google." },
  "Business Intelligence": { when: "You need dashboards and reports that business users can build without SQL.", why: "Not everyone who needs data insights can write SQL. BI tools provide drag-and-drop dashboard builders, scheduled reports, and self-service exploration so business teams can answer their own questions." },
  "Internet Intelligence": { when: "You need global internet traffic data, outage detection, or attack trend analysis.", why: "Understanding internet health - which countries are having outages, what new attack patterns are emerging, how traffic patterns are shifting - requires data from a massive network. Useful for security research, incident response, and planning." },
  "Video Streaming / Transcoding": { when: "You need to upload, transcode, and deliver video on demand with adaptive bitrate.", why: "A single video needs multiple encodings (different resolutions, bitrates, codecs) for adaptive streaming - the player picks the best quality for each viewer's connection. Building this pipeline (ingest, encode, store, deliver) from scratch is months of work." },
  "Image Optimization": { when: "You need to resize, compress, and convert images on the fly per device.", why: "Serving a 4000px JPEG to a mobile phone wastes bandwidth. Image optimization automatically resizes, compresses, and converts to modern formats (WebP, AVIF) per device, often reducing file size 70%+ without visible quality loss." },
  "Live Media Streaming (MoQ)": { when: "You need sub-second live video streaming for interactive broadcasts or auctions.", why: "Traditional live streaming (HLS/RTMP) has 5-30 second latency. For live auctions, sports betting, or interactive broadcasts, that delay is unacceptable. MoQ uses QUIC protocol for sub-second delivery at global scale." },
  "WordPress Optimization": { when: "You run WordPress and want automatic page caching and optimization without stack changes.", why: "WordPress generates HTML dynamically on every page load, hitting PHP and MySQL each time. APO caches the rendered HTML at the edge, serving most requests without touching your origin server at all." },
  "Site Performance": { when: "You want automatic performance improvements without code changes.", why: "Web performance best practices (minify CSS/JS, defer render-blocking scripts, preconnect to origins, use early hints) require code changes. Edge-based optimization applies these automatically to every response." },
  "Database Migration": { when: "You need to migrate a production database to the cloud with minimal downtime.", why: "You can't just dump and restore a production database - that means hours of downtime. Migration services replicate data continuously while your app keeps running, then you cut over in seconds when ready." },
  "Server / VM Migration": { when: "You need to lift-and-shift on-prem VMs to the cloud.", why: "Re-architecting every application for the cloud takes years. VM migration replicates your existing servers as-is, getting you off on-prem hardware quickly. You can modernize later once you're in the cloud." },
  "IoT Platform": { when: "You need to connect, manage, and collect telemetry from thousands of IoT devices.", why: "IoT devices are constrained - limited CPU, intermittent connectivity, deployed in the field. Managing authentication, message routing, firmware updates, and data processing for thousands of them requires purpose-built infrastructure." },
  "MQTT Messaging": { when: "You need a managed MQTT broker for lightweight pub/sub between IoT devices.", why: "HTTP is too heavy for battery-powered IoT devices on unreliable networks. MQTT is designed for this - tiny message overhead, persistent sessions that survive disconnections, and quality-of-service levels for delivery guarantees." },
  "Web3 / Blockchain Gateways": { when: "You need managed access to Ethereum or IPFS without running your own nodes.", why: "Running an Ethereum full node requires hundreds of GB of storage, continuous syncing, and maintenance. Gateways provide API access to blockchain data without running the infrastructure yourself." },
  "SASE Hardware Appliance": { when: "You need a physical appliance at a branch office for local compute and secure connectivity back to cloud.", why: "Branch offices need local networking (WiFi, LAN) that connects securely to headquarters and cloud. A SASE appliance provides this in one box - routing, firewall, VPN, and Zero Trust policy enforcement." },
  "Public DNS Resolver": { when: "You need a fast, privacy-focused recursive DNS resolver for users or devices.", why: "Your ISP's DNS resolver is often slow, logs your queries, and may inject ads or redirect failed lookups. Public resolvers are faster, more private, and support encrypted DNS (DoH/DoT) to prevent eavesdropping." },
  "Time Services": { when: "You need accurate NTP time synchronization for servers, compliance logging, or distributed systems.", why: "Distributed systems need agreed-upon time - TLS certificates expire, DNSSEC signatures have validity windows, log correlation requires synchronized clocks. Inaccurate time causes authentication failures and makes debugging impossible." },
  "Privacy Relay / Proxy": { when: "You need to anonymize user IPs for privacy compliance or consumer privacy features.", why: "IP addresses identify users and their locations. Privacy regulations and user expectations increasingly demand that this information be protected. Privacy relays separate identity from browsing activity cryptographically." },
  "Randomness Beacon": { when: "You need publicly verifiable, unbiased random numbers for lotteries, audits, or crypto protocols.", why: "Random numbers from one server can be faked. A distributed randomness beacon uses multiple independent parties to generate random values that no single party can predict or manipulate - essential for trust in lotteries and protocols." },
  "Key Transparency": { when: "You need to publish and audit public keys so users can verify they haven't been tampered with.", why: "End-to-end encrypted messaging relies on correct public keys. If a server secretly swaps your key for an attacker's, all your messages can be read. Key transparency creates a public, auditable log that makes such tampering detectable." },
};

